import React from 'react';
// eslint-disable-next-line no-unused-vars
import { motion } from 'framer-motion';
import { GripVertical, Edit2, Trash2, Calendar as CalendarIcon } from 'lucide-react';

export const TaskCard = ({ task, onDelete, onEdit, courses, onDragEnd }) => {
  const courseObj = courses?.find(c => c.id === task.course_id);
  const accentColor = courseObj?.color || 'var(--accent-primary)';

  const formatDate = (dateStr) => {
    if (!dateStr) return null;
    try {
      const datePart = typeof dateStr === 'string' ? dateStr.split(/[T ]/)[0] : '';
      if (!datePart) return null;
      const d = new Date(`${datePart}T00:00:00`);
      return d.toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric' });
    } catch { return dateStr; }
  };

  const displayDate = formatDate(task.deadline || task.due_date);

  return (
    <motion.div
      layout
      drag
      dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
      dragElastic={0.9}
      onDragEnd={(event, info) => onDragEnd(task, info)}
      whileDrag={{ 
        scale: 1.05, 
        rotate: 2, 
        zIndex: 100,
        boxShadow: `0 20px 40px rgba(0,0,0,0.4), 0 0 20px ${accentColor}33`,
      }}
      className="glass-panel task-card-alfa"
      style={{
        padding: 'clamp(14px, 2vw, 20px)',
        marginBottom: '16px',
        borderTop: '1px solid var(--border-glass-top)',
        display: 'flex',
        flexDirection: 'column',
        gap: '14px',
        position: 'relative',
        background: 'rgba(255,255,255,0.02)',
        borderRadius: '16px',
        cursor: 'grab',
        touchAction: 'none'
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '12px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flex: 1, minWidth: 0 }}>
          <GripVertical size={14} color="var(--text-muted)" style={{ flexShrink: 0 }} />
          <div style={{ 
            display: 'flex', alignItems: 'center', gap: '8px', 
            background: `${accentColor}15`, padding: '4px 10px', borderRadius: '6px',
            border: `1px solid ${accentColor}33`, maxWidth: '100%', overflow: 'hidden'
          }}>
            <div style={{ width: '6px', height: '6px', borderRadius: '50%', background: accentColor, flexShrink: 0 }} />
            <span style={{ fontSize: '0.75rem', color: 'rgba(255, 255, 255, 0.85)', fontWeight: 800, textTransform: 'uppercase', whiteSpace: 'nowrap' }}>
              {courseObj?.name || 'General'}
            </span>
          </div>
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <motion.button 
            whileHover={{ 
              scale: 1.02, 
              backgroundColor: 'rgba(0, 243, 255, 0.15)', 
              borderColor: 'rgba(0, 243, 255, 0.5)',
              boxShadow: '0 0 15px rgba(0, 243, 255, 0.4), inset 0 0 8px rgba(0, 243, 255, 0.2)'
            }}
            whileTap={{ scale: 0.98 }}
            className="btn-icon-alfa"
            style={{ 
              opacity: 1, 
              cursor: 'pointer', 
              color: '#00f3ff',
              background: 'rgba(0, 243, 255, 0.02)',
              border: '1px solid rgba(0, 243, 255, 0.1)',
              padding: '6px',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'all 0.3s var(--ease-out-quint)'
            }}
            onClick={(e) => { e.stopPropagation(); onEdit(task); }}
          >
            <Edit2 size={15} style={{ filter: 'drop-shadow(0 0 4px rgba(0, 243, 255, 0.5))' }} />
          </motion.button>
          <motion.button 
            whileHover={{ 
              scale: 1.02, 
              backgroundColor: 'rgba(255, 77, 77, 0.15)', 
              borderColor: 'rgba(255, 77, 77, 0.5)',
              boxShadow: '0 0 15px rgba(255, 77, 77, 0.4), inset 0 0 8px rgba(255, 77, 77, 0.2)'
            }}
            whileTap={{ scale: 0.98 }}
            className="btn-icon-alfa"
            style={{ 
              opacity: 1, 
              cursor: 'pointer', 
              color: '#ff4d4d',
              background: 'rgba(255, 77, 77, 0.02)',
              border: '1px solid rgba(255, 77, 77, 0.1)',
              padding: '6px',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'all 0.3s var(--ease-out-quint)'
            }}
            onClick={(e) => { e.stopPropagation(); onDelete(task.id); }}
          >
            <Trash2 size={15} style={{ filter: 'drop-shadow(0 0 4px rgba(255, 77, 77, 0.5))' }} />
          </motion.button>
        </div>
      </div>
      <h4 style={{ margin: 0, fontSize: '1rem', fontWeight: 600, color: 'var(--text-primary)' }}>{task.title}</h4>
      <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid rgba(255,255,255,0.05)', paddingTop: '10px' }}>
        {displayDate && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <CalendarIcon size={12} color="var(--accent-primary)" />
            <span style={{ fontSize: '0.7rem', color: 'var(--accent-primary)', fontWeight: 700 }}>{displayDate}</span>
          </div>
        )}
      </div>
    </motion.div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, Check } from 'lucide-react';

const COLOR_GROUPS = [
  { label: 'Vibrantes', colors: ['#FF5E5E', '#FFB35E', '#FFEB5E', '#B3FF5E', '#5EFF5E', '#5EFFB3', '#5EFAFF'] },
  { label: 'Océano', colors: ['#5EB3FF', '#5E5EFF', '#B35EFF', '#FF5EFF', '#FF5EB3', '#7C3AED', '#2563EB'] },
  { label: 'Pasteles', colors: ['#FCA5A5', '#FDBA74', '#FDE047', '#BEF264', '#86EFAC', '#67E8F9', '#93C5FD'] },
  { label: 'Elegantes', colors: ['#A5B4FC', '#C4B5FD', '#F9A8D4', '#FDA4AF', '#DB2777', '#4F46E5', '#059669'] },
  { label: 'Neutrales', colors: ['#E5E7EB', '#9CA3AF', '#4B5563', '#1F2937', '#000000', '#D97706', '#DC2626'] }
];

const ColorPicker = ({ selectedColor, onSelect, isOpen, onToggle, onClose, t }) => {
  const containerRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        onClose();
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '100%' }}>
      <button
        type="button"
        onClick={onToggle}
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          gap: '12px',
          padding: '12px 16px',
          background: 'var(--bg-glass)',
          border: '1px solid var(--border-glass-top)',
          borderRadius: 'var(--radius-md)',
          cursor: 'pointer',
          transition: 'all 0.3s'
        }}
      >
        <div style={{ width: '24px', height: '24px', borderRadius: '6px', background: selectedColor, border: '1px solid rgba(255,255,255,0.2)' }} />
        <span style={{ flex: 1, textAlign: 'left', fontSize: '0.9rem', fontWeight: 600 }}>{t.tetherColor}</span>
        <ChevronDown size={18} style={{ transform: isOpen ? 'rotate(180deg)' : 'rotate(0)', transition: 'transform 0.3s' }} />
      </button>

      {isOpen && (
        <>
          <div
            onClick={onClose}
            style={{
              position: 'fixed',
              top: 0, left: 0, right: 0, bottom: 0,
              zIndex: 1299,
              background: 'rgba(0,0,0,0.3)'
            }}
          />
          <div style={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 1300,
            padding: '24px',
            background: 'rgba(15, 15, 20, 0.98)',
            backdropFilter: 'blur(30px)',
            border: '1px solid rgba(0, 243, 255, 0.3)',
            borderRadius: '20px',
            boxShadow: '0 0 30px rgba(0, 243, 255, 0.2), 0 12px 40px rgba(0,0,0,0.5)',
            width: '320px'
          }}>
            {COLOR_GROUPS.map(group => (
              <div key={group.label} style={{ marginBottom: '18px' }}>
                <p style={{ fontSize: '0.65rem', fontWeight: 800, color: 'rgba(255,255,255,0.4)', marginBottom: '10px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>{group.label}</p>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '8px' }}>
                  {group.colors.map(c => (
                    <div
                      key={c}
                      onClick={() => { onSelect(c); onClose(); }}
                      style={{
                        width: '100%',
                        aspectRatio: '1',
                        background: c,
                        borderRadius: '8px',
                        cursor: 'pointer',
                        border: selectedColor === c ? '2px solid #fff' : '1px solid rgba(255,255,255,0.1)',
                        boxShadow: selectedColor === c ? `0 0 15px ${c}aa` : 'none',
                        transition: 'transform 0.2s',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                      onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.1)'}
                      onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                    >
                      {selectedColor === c && <Check size={14} color={['#ffffff', '#E5E7EB', '#FDE047'].includes(c) ? '#000' : '#fff'} />}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default ColorPicker;

