import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, Check } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

/**
 * Select custom estilizado con el look cyber-luxe de CampusFlow.
 * Reemplaza <select> nativos que muestran el popup feo del sistema operativo
 * (fondo blanco/azul) en móvil. Ahora el desplegable usa el mismo estilo que
 * los dropdowns de Pomodoro (Objetivo de estudio / Ambiente Sonoro).
 *
 * @param {string} value - id de la opción seleccionada actualmente.
 * @param {(value: string) => void} onChange - callback al seleccionar una opción.
 * @param {{ value: string, label: string }[]} options - opciones disponibles.
 * @param {string} [placeholder] - texto cuando no hay selección.
 * @param {boolean} [required] - si es obligatorio (visual, no valida por sí solo).
 * @param {object} [style] - estilos adicionales al contenedor raíz.
 */
const CustomSelect = ({ value, onChange, options, placeholder = 'Selecciona...', required, style }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef(null);

  // Cerrar al hacer clic fuera
  useEffect(() => {
    if (!isOpen) return;
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, [isOpen]);

  const selectedOption = options.find(o => o.value === value);
  const displayLabel = selectedOption?.label || placeholder;

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '100%', ...style }}>
      {/* Trigger button */}
      <button
        type="button"
        onClick={() => setIsOpen(prev => !prev)}
        style={{
          width: '100%',
          padding: '12px 14px',
          fontSize: '0.85rem',
          fontFamily: 'var(--font-body)',
          background: 'rgba(8, 10, 18, 0.95)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          border: isOpen ? '1px solid rgba(0, 243, 255, 0.4)' : '1px solid rgba(255, 255, 255, 0.1)',
          borderRadius: '10px',
          color: selectedOption ? 'var(--text-primary)' : 'var(--text-muted)',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          transition: 'all 0.2s ease',
          outline: 'none',
          minHeight: '48px',
          boxShadow: isOpen ? '0 0 12px rgba(0, 243, 255, 0.15)' : 'none',
          textAlign: 'left',
        }}
      >
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flex: 1 }}>
          {displayLabel}
        </span>
        <ChevronDown
          size={16}
          style={{
            flexShrink: 0,
            transition: 'transform 0.2s ease',
            transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
            opacity: 0.6,
            color: '#00f3ff'
          }}
        />
      </button>

      {/* Dropdown */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={{ duration: 0.15, ease: [0.4, 0, 0.2, 1] }}
            style={{
              position: 'absolute',
              top: 'calc(100% + 6px)',
              left: 0,
              right: 0,
              zIndex: 200,
              background: 'rgba(8, 10, 18, 0.98)',
              backdropFilter: 'blur(20px) saturate(180%)',
              WebkitBackdropFilter: 'blur(20px) saturate(180%)',
              border: '1px solid rgba(0, 243, 255, 0.3)',
              borderRadius: '12px',
              boxShadow: '0 16px 40px rgba(0, 0, 0, 0.85), 0 0 0 1px rgba(0, 0, 0, 0.4), inset 0 0 12px rgba(0, 243, 255, 0.06)',
              padding: '6px',
              maxHeight: 'min(260px, 45vh)',
              overflowY: 'auto',
              display: 'flex',
              flexDirection: 'column',
              gap: '2px',
            }}
          >
            {options.map(option => {
              const isSelected = option.value === value;
              return (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => {
                    onChange(option.value);
                    setIsOpen(false);
                  }}
                  style={{
                    width: '100%',
                    padding: '12px 14px',
                    border: 'none',
                    borderRadius: '8px',
                    background: isSelected ? 'rgba(0, 243, 255, 0.14)' : 'transparent',
                    color: isSelected ? '#00f3ff' : 'rgba(255, 255, 255, 0.88)',
                    fontSize: '0.88rem',
                    fontFamily: 'var(--font-body)',
                    fontWeight: isSelected ? 800 : 600,
                    cursor: 'pointer',
                    textAlign: 'left',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    transition: 'all 0.15s ease',
                    outline: 'none',
                    minHeight: '44px',
                  }}
                  onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'rgba(255, 255, 255, 0.06)'; }}
                  onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
                >
                  <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {option.label}
                  </span>
                  {isSelected && <Check size={16} style={{ color: '#00f3ff', flexShrink: 0 }} />}
                </button>
              );
            })}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CustomSelect;

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabaseClient';
import { Lock, AlertCircle, CheckCircle, Loader } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const MFAVerificationModal = ({ isOpen, onVerificationSuccess, userId }) => {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [attempt, setAttempt] = useState(0);

  // Reset cuando se abre el modal
  useEffect(() => {
    if (isOpen) {
      setCode('');
      setError('');
      setSuccess('');
      setAttempt(0);
    }
  }, [isOpen]);

  // Limpieza automática de mensajes
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(''), 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  const handleCodeChange = (e) => {
    const value = e.target.value.replace(/\D/g, ''); // Solo números
    if (value.length <= 6) {
      setCode(value);
    }
  };

  const handleVerify = async (e) => {
    e.preventDefault();
    if (!code || code.length !== 6) {
      setError('El código debe tener exactamente 6 dígitos');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      // Obtener factores MFA (TOTP)
      const { data: factors, error: factorsError } = await supabase.auth.mfa.listFactors();

      if (factorsError) throw factorsError;
      if (!factors?.totp?.length) {
        throw new Error('No se encontró factor TOTP. Habilita MFA primero.');
      }

      const totpFactor = factors.totp[0];

      // Crear challenge MFA
      const { data: challengeData, error: challengeError } = await supabase.auth.mfa.challenge({
        factorId: totpFactor.id
      });

      if (challengeError) throw challengeError;

      // Verificar el código
      const { data: verifyData, error: verifyError } = await supabase.auth.mfa.verify({
        factorId: totpFactor.id,
        challengeId: challengeData.id,
        code
      });

      if (verifyError) throw verifyError;

      setSuccess('✓ Verificación exitosa. Accediendo a la app...');
      setAttempt(0);

      // Callback después de 800ms
      setTimeout(() => {
        onVerificationSuccess();
      }, 800);

    } catch (err) {
      const newAttempt = attempt + 1;
      setAttempt(newAttempt);

      let errorMsg = err.message || 'Error verificando el código';
      
      // Mensajes más amigables
      if (errorMsg.includes('Invalid authentication code')) {
        errorMsg = 'Código incorrecto. Intenta de nuevo.';
      } else if (errorMsg.includes('Invalid TOTP code')) {
        errorMsg = 'Código expirado o inválido. Intenta con uno nuevo.';
      } else if (errorMsg.includes('No TOTP factor')) {
        errorMsg = 'MFA no está configurado correctamente.';
      }

      setError(errorMsg);
      setCode('');

      // Bloquea después de 5 intentos fallidos
      if (newAttempt >= 5) {
        setError('Demasiados intentos fallidos. Por favor, intenta más tarde.');
      }

      console.error('MFA Verification Error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50"
        >
          <motion.div
            initial={{ scale: 0.95, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.95, opacity: 0 }}
            transition={{ type: 'spring', damping: 20, stiffness: 150 }}
            className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl p-8 w-full max-w-md mx-4"
          >
            {/* Header */}
            <div className="flex items-center justify-center mb-6">
              <div className="p-3 bg-blue-100 dark:bg-blue-900 rounded-full">
                <Lock className="w-6 h-6 text-blue-600 dark:text-blue-400" />
              </div>
            </div>

            <h2 className="text-2xl font-bold text-center mb-2 dark:text-white">
              Verificación de Seguridad
            </h2>
            <p className="text-gray-600 dark:text-gray-400 text-center text-sm mb-6">
              Ingresa el código de 6 dígitos de tu autenticador para acceder a CampusFlow
            </p>

            {/* Intentos restantes */}
            {attempt > 0 && attempt < 5 && (
              <div className="mb-4 p-3 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg border border-yellow-200 dark:border-yellow-700">
                <p className="text-xs text-yellow-700 dark:text-yellow-400">
                  Intento {attempt} de 5
                </p>
              </div>
            )}

            <form onSubmit={handleVerify} className="space-y-4">
              {/* Input de código */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Código de 6 dígitos
                </label>
                <input
                  type="text"
                  inputMode="numeric"
                  value={code}
                  onChange={handleCodeChange}
                  placeholder="000000"
                  maxLength="6"
                  disabled={loading || attempt >= 5}
                  className="w-full px-4 py-3 text-center text-2xl font-mono font-bold tracking-widest border-2 border-gray-200 dark:border-gray-700 dark:bg-gray-800 dark:text-white rounded-lg focus:outline-none focus:border-blue-500 dark:focus:border-blue-400 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                />
              </div>

              {/* Mensajes de error */}
              {error && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex items-start space-x-3 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 rounded-lg"
                >
                  <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-red-700 dark:text-red-400">{error}</p>
                </motion.div>
              )}

              {/* Mensajes de éxito */}
              {success && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex items-start space-x-3 p-3 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 rounded-lg"
                >
                  <CheckCircle className="w-5 h-5 text-green-600 dark:text-green-400 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-green-700 dark:text-green-400">{success}</p>
                </motion.div>
              )}

              {/* Botón de verificación */}
              <motion.button
                type="submit"
                disabled={loading || code.length !== 6 || attempt >= 5}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="w-full py-3 bg-blue-600 dark:bg-blue-500 hover:bg-blue-700 dark:hover:bg-blue-600 text-white font-semibold rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
              >
                {loading ? (
                  <>
                    <Loader className="w-4 h-4 animate-spin" />
                    <span>Verificando...</span>
                  </>
                ) : (
                  <span>Verificar Código</span>
                )}
              </motion.button>
            </form>

            {/* Ayuda */}
            <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
              <p className="text-xs text-gray-500 dark:text-gray-400 text-center">
                ¿Necesitas ayuda? Abre tu aplicación autenticadora y copia el código actual
              </p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

