    border: '1px solid rgba(90, 120, 150, 0.18)',
    borderRadius: '16px',
    boxShadow: '0 8px 24px rgba(60, 80, 100, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.65)',
