                    height: '100%',
                    borderRadius: '10px',
                    background: `linear-gradient(90deg, #00f3ff 0%, #bc13fe 50%, #00ff88 100%)`,
                    boxShadow: '0 0 15px rgba(0, 243, 255, 0.6), inset 0 0 10px rgba(255, 255, 255, 0.2)',
