import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useSettings } from '../context/SettingsContext';
import { usePlanners } from '../hooks/usePlanners';
import { Clock, Calendar, CheckCircle2, Circle, Folder, Plus, Pencil, ArrowLeft, Sun, Moon, Sunset, BarChart2, Trash2, ChevronDown, Play } from 'lucide-react';
import { useCourses } from '../hooks/useCourses';
import { useTasksContext } from '../context/TaskContext';
import ColorPicker from '../components/ui/ColorPicker';
import WeeklyPlannerSkeleton from '../components/ui/WeeklyPlannerSkeleton';
import { motion, AnimatePresence } from 'framer-motion';
import { prefetchAnalyticsData } from '../lib/prefetchAnalyticsData';

const DAY_OPTIONS = [
  { value: 'monday', label: 'Lunes' },
  { value: 'tuesday', label: 'Martes' },
  { value: 'wednesday', label: 'Miércoles' },
  { value: 'thursday', label: 'Jueves' },
  { value: 'friday', label: 'Viernes' },
  { value: 'saturday', label: 'Sábado' },
  { value: 'sunday', label: 'Domingo' }
];

const TIME_OPTIONS = [
