  { value: 'afternoon', label: 'Tarde', icon: Sunset, accent: '#ff8a5b', description: 'Bloque de ejecución' },
  { value: 'night', label: 'Noche', icon: Moon, accent: '#8d7dff', description: 'Ritmo profundo' }
];

const BLOCK_TYPE_OPTIONS = [
